"use client";
import { TriangleAlert, LoaderCircle } from "lucide-react";
import { useEffect, useRef, useState, useTransition } from "react";
import { signOut } from "next-auth/react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Feedback } from "@/components/forms";
import { useSuccessNotification } from "@/components/notifications";
import { deleteAccount } from "@/lib/launch-actions";
import { deleteHistory } from "@/lib/history-actions";
import type { ActionResult } from "@/lib/errors";
import { SettingsPanel } from "./SettingsPanel";
import styles from "./settings.module.css";

export function DangerZone({ email }: { email: string }) {
  return (
    <SettingsPanel
      id="danger"
      title="Danger zone"
      icon={TriangleAlert}
      danger
      description="These actions can’t be undone."
    >
      <div
        className={`flex justify-between items-center flex-wrap gap-3.5 py-4 px-0`}
      >
        <div>
          <h3 className="text-sm font-bold">Delete history</h3>
          <p
            className={`text-[var(--settings-muted)] text-[14px] leading-[1.65]`}
          >
            Remove your sent message history.
          </p>
        </div>
        <DeleteHistory />
      </div>
      <div
        className={`flex justify-between items-center flex-wrap gap-3.5 pt-4 pb-0 px-0 border-t border-dotted border-separator`}
      >
        <div>
          <h3 className="text-sm font-bold">Delete account</h3>
          <p
            className={`text-[var(--settings-muted)] text-[14px] leading-[1.65]`}
          >
            Permanently remove your account and all data.
          </p>
        </div>
        <DeleteAccount email={email} />
      </div>
    </SettingsPanel>
  );
}
function DeleteAccount({ email }: { email: string }) {
  const [pending, start] = useTransition();
  const [confirmation, setConfirmation] = useState("");
  const [deletionResult, setDeletionResult] = useState<ActionResult>();
  const [requested, setRequested] = useState(false);
  const [signingOut, setSigningOut] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const success = useRef<HTMLParagraphElement>(null);
  async function finishSignOut() {
    setSigningOut(true);
    setDeletionResult(undefined);
    try {
      await signOut({ redirectTo: "/?deleted=1" });
    } catch {
      setDeletionResult({
        ok: false,
        message: "Could not sign out. Please retry sign-out.",
      });
      setSigningOut(false);
    }
  }
  useEffect(() => {
    if (!requested) return;
    success.current?.focus();
    const timer = setTimeout(() => {
      void finishSignOut();
    }, 2500);
    return () => clearTimeout(timer);
  }, [requested]);
  const dialog = useRef<HTMLDialogElement>(null);
  return (
    <>
      <Button
        className={`${styles.dangerButton} inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer [border:1px_solid_var(--settings-danger-border)] text-[var(--settings-red)] [background:transparent] shadow-[var(--appearance-shadow,_none)] css-hover:[background:var(--settings-danger-background)]`}
        variant="outline"
        disabled={pending}
        ref={trigger}
        onClick={() => {
          setConfirmation("");
          setDeletionResult(undefined);
          dialog.current?.showModal();
        }}
      >
        Delete account
      </Button>
      <dialog
        ref={dialog}
        className={`${styles.dialog} m-auto w-[calc(100%_-_2rem)] max-w-128 max-h-[calc(100dvh_-_2rem)] overflow-y-auto [border:1px_solid_var(--settings-strong)] rounded-[var(--appearance-radius,_24px)] p-7 [background:var(--settings-elevated)] text-[var(--settings-text)] shadow-[var(--appearance-shadow,_0_16px_64px_var(--color-settings-box-shadow-35))] space-y-4`}
        aria-labelledby="delete-account-title"
        aria-describedby={
          requested ? "delete-account-success" : "delete-account-warning"
        }
        onCancel={(event) => {
          if (pending || requested) event.preventDefault();
        }}
        onClose={() => trigger.current?.focus()}
      >
        <h2 id="delete-account-title" className="text-xl">
          {requested
            ? "Account deletion requested"
            : "Delete your Mailloop account?"}
        </h2>
        {requested ? (
          <>
            <p
              id="delete-account-success"
              ref={success}
              tabIndex={-1}
              role="status"
              className="text-sm leading-6"
            >
              Account deletion requested. You’ll be signed out shortly.
            </p>
            {deletionResult?.ok === false && (
              <>
                <Feedback result={deletionResult} />
                <Button
                  variant="outline"
                  className={`${styles.secondary} secondary-button inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction [border:1px_solid_var(--settings-strong)] text-[var(--settings-text)] [background:transparent] shadow-[var(--appearance-shadow,_none)]`}
                  disabled={signingOut}
                  onClick={() => void finishSignOut()}
                >
                  {signingOut ? "Signing out…" : "Retry sign-out"}
                </Button>
              </>
            )}
          </>
        ) : (
          <>
            <div
              id="delete-account-warning"
              className="flex gap-3 rounded-sm bg-warning-soft p-3 text-sm leading-6 text-warning"
            >
              <TriangleAlert
                className="mt-1 size-5 shrink-0"
                aria-hidden="true"
              />
              <p>
                <strong>This request can’t be undone.</strong>
              </p>
            </div>
            <ul className="list-disc space-y-2 pl-5 text-sm leading-6 text-body">
              <li>
                <strong className="text-foreground">
                  Access disabled immediately.
                </strong>{" "}
                Queued emails are cancelled where possible; active sends may
                still finish.
              </li>
              <li>
                <strong className="text-foreground">
                  Same Google account blocked while deletion is pending.
                </strong>{" "}
                You cannot sign in or create another Mailloop account with it.
              </li>
              <li>
                <strong className="text-foreground">
                  Irreversible cleanup runs daily.
                </strong>{" "}
                After a minimum 15-minute waiting period, the next daily run
                removes your profile, contacts, templates, history, and owned
                PDFs, with a 30-day target from the original request.
                Subscription cancellation is attempted immediately, including
                pending checkouts. Google revocation and storage deletion retry
                independently. A keyed identity hash and minimal provider
                identifiers keep unresolved cleanup recoverable. External
                outages can delay completion.
              </li>
              <li>Emails remain in Gmail and recipients’ inboxes.</li>
            </ul>
            <p className="text-sm text-body">
              Download your data first if you need a copy.
            </p>
            <label htmlFor="delete-email" className="block break-all text-sm">
              Type {email} to confirm
            </label>
            <Input
              className={`placeholder:text-[var(--settings-muted)] h-11.5 max-w-full rounded-[var(--appearance-radius,_14px)] [border:1px_solid_var(--settings-border)] [background:var(--settings-inset)] py-0 px-4 text-[var(--settings-text)] text-[14px] leading-5`}
              id="delete-email"
              type="email"
              autoComplete="off"
              spellCheck={false}
              disabled={pending}
              value={confirmation}
              onChange={(e) => setConfirmation(e.target.value)}
            />
            <div className="flex flex-wrap gap-3">
              <Button
                className={`${styles.dangerButton} inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer [border:1px_solid_var(--settings-danger-border)] text-[var(--settings-red)] [background:transparent] shadow-[var(--appearance-shadow,_none)] css-hover:[background:var(--settings-danger-background)]`}
                variant="destructive"
                aria-busy={pending}
                disabled={pending || confirmation !== email}
                onClick={() =>
                  start(async () => {
                    setDeletionResult(undefined);
                    try {
                      const response = await deleteAccount(confirmation);
                      if (response.ok) setRequested(true);
                      else setDeletionResult(response);
                    } catch {
                      setDeletionResult({
                        ok: false,
                        message: "Could not request deletion. Try again.",
                      });
                    }
                  })
                }
              >
                {pending && (
                  <LoaderCircle
                    className="size-4 animate-spin"
                    aria-hidden="true"
                  />
                )}
                {pending ? "Requesting deletion…" : "Request account deletion"}
              </Button>
              <Button
                autoFocus
                className={`${styles.secondary} secondary-button inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction [border:1px_solid_var(--settings-strong)] text-[var(--settings-text)] [background:transparent] shadow-[var(--appearance-shadow,_none)]`}
                variant="outline"
                disabled={pending}
                onClick={() => dialog.current?.close()}
              >
                Cancel
              </Button>
            </div>
            <Feedback result={deletionResult} />
          </>
        )}
      </dialog>
    </>
  );
}
function DeleteHistory() {
  const dialog = useRef<HTMLDialogElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const [pending, start] = useTransition();
  const [result, setResult] = useState<ActionResult>();
  const [confirmation, setConfirmation] = useState("");
  const notify = useSuccessNotification();
  return (
    <div>
      <Button
        ref={trigger}
        className={`${styles.dangerButton} inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer [border:1px_solid_var(--settings-danger-border)] text-[var(--settings-red)] [background:transparent] shadow-[var(--appearance-shadow,_none)] css-hover:[background:var(--settings-danger-background)]`}
        variant="outline"
        onClick={() => {
          setResult(undefined);
          setConfirmation("");
          dialog.current?.showModal();
        }}
      >
        Delete history
      </Button>
      <dialog
        ref={dialog}
        className={`${styles.dialog} m-auto w-[calc(100%_-_2rem)] max-w-128 max-h-[calc(100dvh_-_2rem)] overflow-y-auto [border:1px_solid_var(--settings-strong)] rounded-[var(--appearance-radius,_24px)] p-7 [background:var(--settings-elevated)] text-[var(--settings-text)] shadow-[var(--appearance-shadow,_0_16px_64px_var(--color-settings-box-shadow-35))] space-y-4`}
        aria-labelledby="delete-history-title"
        aria-describedby="delete-history-warning"
        onCancel={(event) => {
          if (pending) event.preventDefault();
        }}
        onClose={() => trigger.current?.focus()}
      >
        <h2 id="delete-history-title" className="text-xl">
          Delete completed history?
        </h2>
        <div
          id="delete-history-warning"
          className="flex gap-3 rounded-sm bg-warning-soft p-3 text-sm leading-6 text-warning"
        >
          <TriangleAlert className="mt-1 size-5 shrink-0" aria-hidden="true" />
          <p>
            <strong>
              Completed history will be permanently deleted. This can’t be
              undone.
            </strong>
          </p>
        </div>
        <ul className="list-disc space-y-2 pl-5 text-sm leading-6 text-body">
          <li>
            <strong className="text-foreground">
              Completed messages and follow-up reminders
            </strong>{" "}
            will be removed.
          </li>
          <li>
            <strong className="text-foreground">
              Queued, in-progress, and review-needed deliveries
            </strong>{" "}
            remain.
          </li>
          <li>Emails in Gmail are unchanged.</li>
        </ul>
        <p className="text-xs leading-5 text-body">
          Sending limits and duplicate-send protection still apply. We retain
          your account ID, recipient address, and creation and send times as
          delivery safeguards until account deletion. Active campaigns also
          retain recipient roles and original recipient counts so plan limits
          continue to apply; deleted message content is removed.
        </p>
        <p className="text-sm text-body">
          Download your data first if you need a copy.
        </p>
        <label htmlFor="delete-history-confirmation" className="block text-sm">
          Type Delete history to confirm
        </label>
        <Input
          className={`placeholder:text-[var(--settings-muted)] h-11.5 max-w-full rounded-[var(--appearance-radius,_14px)] [border:1px_solid_var(--settings-border)] [background:var(--settings-inset)] py-0 px-4 text-[var(--settings-text)] text-[14px] leading-5`}
          id="delete-history-confirmation"
          autoComplete="off"
          spellCheck={false}
          disabled={pending}
          value={confirmation}
          onChange={(event) => setConfirmation(event.target.value)}
        />
        <div className="flex flex-wrap gap-3">
          <Button
            autoFocus
            className={`${styles.secondary} secondary-button inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer button-interaction [border:1px_solid_var(--settings-strong)] text-[var(--settings-text)] [background:transparent] shadow-[var(--appearance-shadow,_none)]`}
            variant="outline"
            disabled={pending}
            onClick={() => dialog.current?.close()}
          >
            Cancel
          </Button>
          <Button
            className={`${styles.dangerButton} inline-flex items-center justify-center gap-2 min-h-11.5 max-w-full py-[11px] px-5.5 rounded-full [font:700_14px/1.4_var(--font-plus-jakarta),_sans-serif] text-center no-underline whitespace-normal cursor-pointer [border:1px_solid_var(--settings-danger-border)] text-[var(--settings-red)] [background:transparent] shadow-[var(--appearance-shadow,_none)] css-hover:[background:var(--settings-danger-background)]`}
            variant="destructive"
            disabled={pending || confirmation !== "Delete history"}
            aria-busy={pending}
            onClick={() =>
              start(async () => {
                try {
                  const response = await deleteHistory();
                  setResult(response);
                  if (response.ok) {
                    dialog.current?.close();
                    notify(response.message);
                  }
                } catch {
                  setResult({
                    ok: false,
                    message: "Could not delete history. Please try again.",
                  });
                }
              })
            }
          >
            {pending ? "Deleting…" : "Delete history"}
          </Button>
        </div>
        {result?.ok === false && <Feedback result={result} />}
      </dialog>
    </div>
  );
}
